        frame.fill(&Path::circle(Point::new(100.0, 150.0), 45.0), Color::from_rgb(0.0, 1.0, 0.0));
        vec![frame.into_geometry()]
    }
}

fn view<'a>() -> Element<'a, ()> {
    scrollable(canvas(Tall).width(200).height(200)).height(100).anchor_bottom().boxed()
}

fn main() {
    env_logger::init();
    let out = std::env::args().nth(1).expect("output path");
    let mut ui = iced_test::Simulator::with_size(iced_test::core::Settings::default(), Size::new(220.0, 120.0), view());
